/* --- DomeOS AI attachments --- */
function __domeSize(n) {
    if (!n) return '0 B';
    if (n < 1024) return n + ' B';
    if (n < 1048576) return (n / 1024).toFixed(1) + ' KB';
    return (n / 1048576).toFixed(1) + ' MB';
}
function __domeIsText(name, mime) {
    if (mime && mime.indexOf('text/') === 0) return true;
    if (mime && /^application\/(json|xml|x-yaml|javascript|ecmascript|typescript|sql|x-sh|x-httpd-php|ld\+json|x-ndjson|toml|csv)$/.test(mime)) return true;
    const ext = (String(name || '').split('.').pop() || '').toLowerCase();
    return 'txt md markdown mdx json jsonl ndjson yml yaml toml ini cfg conf config log csv tsv xml html htm xhtml css scss sass less js mjs cjs jsx ts tsx mts cts vue svelte astro py pyw rb go rs java kt kts scala c h cc cpp cxx hpp hh cs php swift m mm sh bash zsh fish ps1 bat cmd sql pl lua r dart ex exs erl hs clj elm groovy gradle gitignore gitattributes env dockerfile makefile cmake mk graphql gql proto patch diff srt vtt po properties tf tfvars hcl nix'.split(' ').indexOf(ext) >= 0;
}
/** drag / drop / paste entry point: images, readable text, and everything else */
function __domeAddFiles(files, setter) {
    const list = Array.from(files || []).filter(function (f) { return f && (f.size || f.type || f.name); });
    if (!list.length) return false;
    list.slice(0, 8).forEach(function (f) {
        const name = f.name || 'file';
        const mime = f.type || '';
        const size = f.size || 0;
        const push = function (item) { setter(function (prev) { return prev.concat([item]).slice(0, 8); }); };
        if (mime.indexOf('image/') === 0) {
            const fr = new FileReader();
            fr.onload = function () {
                const raw = String(fr.result || '');
                const b64 = raw.split(',')[1] || '';
                if (!b64) return;
                const img = new Image();
                img.onload = function () {
                    const scale = Math.min(1, 1568 / Math.max(img.width || 1, img.height || 1));
                    if (scale >= 1) { push({ kind: 'image', name: name, mime: mime, size: size, data: b64 }); return; }
                    try {
                        const cv = document.createElement('canvas');
                        cv.width = Math.max(1, Math.round(img.width * scale));
                        cv.height = Math.max(1, Math.round(img.height * scale));
                        cv.getContext('2d').drawImage(img, 0, 0, cv.width, cv.height);
                        push({ kind: 'image', name: name, mime: 'image/png', size: size, data: String(cv.toDataURL('image/png')).split(',')[1] || b64 });
                    } catch (e) { push({ kind: 'image', name: name, mime: mime, size: size, data: b64 }); }
                };
                img.onerror = function () { push({ kind: 'image', name: name, mime: mime, size: size, data: b64 }); };
                img.src = raw;
            };
            fr.readAsDataURL(f);
            return;
        }
        if (__domeIsText(name, mime)) {
            const fr = new FileReader();
            fr.onload = function () {
                let txt = String(fr.result || '');
                if (txt.length > 200000) txt = txt.slice(0, 200000) + '\n...(已截断)';
                push({ kind: 'text', name: name, mime: mime || 'text/plain', size: size, text: txt });
            };
            fr.onerror = function () { push({ kind: 'file', name: name, mime: mime, size: size }); };
            fr.readAsText(f);
            return;
        }
        push({ kind: 'file', name: name, mime: mime, size: size });
    });
    return true;
}
function __domePickFiles(setter) {
    const inp = document.createElement('input');
    inp.type = 'file'; inp.multiple = true;
    inp.onchange = function () { __domeAddFiles(inp.files, setter); };
    inp.click();
}
/** the text half of the user turn: message + the attachments the model can read */
function __domeWireText(text, atts) {
    const parts = [];
    if (text) parts.push(text);
    for (const a of atts) {
        if (a.kind === 'text') parts.push('【附件 ' + a.name + '】\n```\n' + (a.text || '') + '\n```');
        else if (a.kind === 'file') parts.push('【附件 ' + a.name + '（' + (a.mime || '未知类型') + '，' + __domeSize(a.size) + '）】该文件为二进制内容，无法直接读取，请告知用户。');
    }
    return parts.join('\n\n');
}
["dragover", "drop"].forEach(function (ev) { document.addEventListener(ev, function (e) { e.preventDefault(); }, false); });
